/**
 * Mock tenant + dispenser registry, persisted to localStorage so admin edits survive reloads.
 * Replace with the real backend. Note: a site served over HTTPS cannot call a dispenser's
 * plain-HTTP LAN IP directly (mixed content), so production calls should go through a relay.
 */
import { MAX_TRAY_COUNT, TRAY_COUNT } from '../data';
import type { Dispenser, TenantSettings, Tray } from '../types';

const KEY = 'jaime.admin.v1';
const wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

interface Store {
  tenant: TenantSettings;
  dispensers: Dispenser[];
}

const emptyTrays = (): Tray[] =>
  Array.from({ length: TRAY_COUNT }, (_, i) => ({ slot: i + 1, flavorId: null, count: 0 }));

function seed(): Store {
  const trays = emptyTrays();
  [
    ['blue-raspberry', 18],
    ['green-apple', 18],
    ['bubble-gum', 16],
    ['buttered-popcorn', 25],
    ['dr-pepper', 24],
  ].forEach(([flavorId, count], i) => {
    trays[i] = { slot: i + 1, flavorId: flavorId as string, count: count as number };
  });
  return {
    tenant: {
      name: "Maker's Lab NYC",
      language: 'English',
      devicesEnabled: true,
      users: [{ email: 'talia.n.pannell@accenture.com', isCurrentUser: true }],
    },
    dispensers: [
      { id: 'd825cbf1388', name: 'dispenser-d825cbf1388', ip: '192.168.1.42', port: 80, online: false, lastSeen: null, trays },
    ],
  };
}

function load(): Store {
  try {
    const raw = localStorage.getItem(KEY);
    if (raw) {
      const parsed = JSON.parse(raw) as Store;
      if (parsed?.tenant && Array.isArray(parsed.dispensers)) return parsed;
    }
  } catch {
    // Corrupt or unavailable storage: fall back to seed data.
  }
  return seed();
}

let store = load();

const CHANGE_EVENT = 'jaime:admin-change';

function persist() {
  try {
    localStorage.setItem(KEY, JSON.stringify(store));
  } catch {
    // Storage full/blocked; keep the in-memory copy.
  }
  window.dispatchEvent(new Event(CHANGE_EVENT));
}

/** Calls `cb` whenever tenant/dispenser data changes in this tab or another tab. Returns an unsubscribe fn. */
export function onAdminChange(cb: () => void): () => void {
  const onStorage = (e: StorageEvent) => {
    if (e.key === KEY) cb();
  };
  window.addEventListener('storage', onStorage);
  window.addEventListener(CHANGE_EVENT, cb);
  return () => {
    window.removeEventListener('storage', onStorage);
    window.removeEventListener(CHANGE_EVENT, cb);
  };
}

/** The dispenser the demo uses: the first online one, else the first registered. */
export const pickActiveDispenser = <T extends { online: boolean }>(list: T[]): T | undefined =>
  list.find((d) => d.online) ?? list[0];

const IPV4_RE = /^(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)(\.(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)){3}$/;

export const isValidIPv4 = (ip: string) => IPV4_RE.test(ip.trim());
export const isValidPort = (port: number) => Number.isInteger(port) && port >= 1 && port <= 65535;

export async function getTenant(): Promise<TenantSettings> {
  await wait(100);
  return structuredClone(store.tenant);
}

export async function saveTenant(next: TenantSettings): Promise<TenantSettings> {
  await wait(200);
  store.tenant = structuredClone(next);
  persist();
  return structuredClone(store.tenant);
}

export async function listDispensers(): Promise<Dispenser[]> {
  await wait(100);
  return structuredClone(store.dispensers);
}

export async function addDispenser(input: { name: string; ip: string; port: number }): Promise<Dispenser> {
  const name = input.name.trim().slice(0, 60);
  const ip = input.ip.trim();
  if (!name || !isValidIPv4(ip) || !isValidPort(input.port)) throw new Error('Invalid dispenser details');
  if (store.dispensers.some((d) => d.ip === ip && d.port === input.port)) throw new Error('That address is already registered');
  await wait(200);
  const dispenser: Dispenser = {
    id: crypto.randomUUID(),
    name,
    ip,
    port: input.port,
    online: false,
    lastSeen: null,
    trays: emptyTrays(),
  };
  store.dispensers = [...store.dispensers, dispenser];
  persist();
  return structuredClone(dispenser);
}

export async function removeDispenser(id: string): Promise<void> {
  await wait(150);
  store.dispensers = store.dispensers.filter((d) => d.id !== id);
  persist();
}

/** Mock ping. Real version: GET http(s)://{ip}:{port}/status via the relay, with a timeout. */
export async function testConnection(id: string): Promise<Dispenser> {
  await wait(800);
  store.dispensers = store.dispensers.map((d) =>
    d.id === id ? { ...d, online: true, lastSeen: new Date().toISOString() } : d,
  );
  persist();
  return structuredClone(store.dispensers.find((d) => d.id === id)!);
}

export async function saveTrays(id: string, trays: Tray[]): Promise<Dispenser> {
  const clean = trays.slice(0, TRAY_COUNT).map((t, i) => ({
    slot: i + 1,
    flavorId: t.flavorId,
    count: t.flavorId ? Math.max(0, Math.min(MAX_TRAY_COUNT, Math.floor(t.count) || 0)) : 0,
  }));
  await wait(250);
  store.dispensers = store.dispensers.map((d) => (d.id === id ? { ...d, trays: clean } : d));
  persist();
  return structuredClone(store.dispensers.find((d) => d.id === id)!);
}

/**
 * Bean stock of the dispenser the demo dispenses from (first online one, else the first registered).
 * Re-reads storage so tray edits made in another tab are picked up.
 */
export async function getActiveStock(): Promise<{ dispenserId: string | null; stock: Record<string, number> }> {
  store = load();
  await wait(100);
  const active = pickActiveDispenser(store.dispensers);
  const stock: Record<string, number> = {};
  if (active && store.tenant.devicesEnabled) {
    for (const t of active.trays) {
      if (t.flavorId && t.count > 0) stock[t.flavorId] = (stock[t.flavorId] ?? 0) + t.count;
    }
  }
  return { dispenserId: active?.id ?? null, stock };
}

/** Deducts dispensed beans from the dispenser's trays, draining lower-numbered trays first. */
export async function consumeBeans(dispenserId: string, items: { flavorId: string; count: number }[]): Promise<void> {
  store = load();
  const dispenser = store.dispensers.find((d) => d.id === dispenserId);
  if (!dispenser) return;
  for (const item of items) {
    let remaining = item.count;
    for (const tray of dispenser.trays) {
      if (remaining <= 0) break;
      if (tray.flavorId !== item.flavorId) continue;
      const take = Math.min(tray.count, remaining);
      tray.count -= take;
      remaining -= take;
    }
  }
  persist();
}
